head.script:
scwin.onpageload = function() {
    grid02.setColumnNodeSet('a', 'data:dataList2', 'name', 'code');
    grid02.setColumnNodeSet('b', 'data:dataList2', 'name', 'code');
    var codeData = [{
        'code': '0',
        'name': '가',
        'gbn': '1'
    }, {
        'code': '1',
        'name': '나',
        'gbn': '1'
    }, {
        'code': '2',
        'name': '다',
        'gbn': '2'
    }, {
        'code': '3',
        'name': '라',
        'gbn': '2'
    }];
    dataList2.setJSON(codeData);
    var arrData = [];
    for (var i = 0; i < 200; i++) {
        var obj = {
            'a': i % 4,
            'b': i % 4,
            'c': 'c' + i,
            'd': 'd' + i
        };
        arrData.push(obj);
    }
    dataList1.setJSON(arrData);
};
scwin.onpageunload = function() {};
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById(id);
    scwin.fireDbClick(el);
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid02_column5').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid02_cell_1_2').blur()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid02_cell_1_2').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid02_cell_1_2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick('grid02_cell_1_2')");
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('wq_uuid_6_cell_1_0').innerText ==  ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
